#!/usr/bin/env python3
import ast, hashlib, os, sys, time
from pathlib import Path
BASE_SHA = "350a6d53ce7c9d57286d766493f9d5148eae94d1a86bcb6fcd82b81daeccc3d1"
LAYER = "# EMBYFLOW_THEINTRODB_TEST_V1\n# Independent implementation using the documented TheIntroDB v3 API.\n# Test only: no server writes; no credentials sent to TheIntroDB.\n\ndef _eftidb_log(message):\n    try:\n        with open('/tmp/embyflow_theintrodb_test.log', 'a') as out:\n            out.write(time.strftime('%Y-%m-%d %H:%M:%S ') + message + '\\n')\n    except Exception:\n        pass\n\n\ndef _eftidb_ranges(data, duration_ms):\n    # Ambiguous/multiple intro ranges are intentionally left alone in V1.\n    answer = {}\n    intros = data.get('intro') or []\n    if isinstance(intros, list) and len(intros) == 1:\n        x = intros[0]\n        if isinstance(x, dict):\n            start, end = x.get('start_ms'), x.get('end_ms')\n            start = 0 if start is None else start\n            if (type(start) is int and type(end) is int\n                    and 0 <= start < end <= duration_ms\n                    and 5000 <= end - start <= 300000\n                    and end <= duration_ms * 0.5):\n                answer.update(intro_start=start * 10000, intro_end=end * 10000)\n    credits = data.get('credits') or []\n    # Only a final range extending to EOF: retain intermediate credit scenes.\n    if isinstance(credits, list):\n        candidates = []\n        for x in credits:\n            if not isinstance(x, dict):\n                continue\n            start, end = x.get('start_ms'), x.get('end_ms')\n            if (type(start) is int and duration_ms * 0.8 <= start < duration_ms\n                    and (end is None or (type(end) is int\n                         and duration_ms - 2000 <= end <= duration_ms))):\n                candidates.append(start)\n        if candidates:\n            answer['credits_start'] = max(candidates) * 10000\n    return answer\n\n\ndef _eftidb_fallback(self, normalized):\n    # Preserve existing server markers, including partial marker sets.\n    if normalized.get('raw_marker_count'):\n        return normalized\n    try:\n        item = dict((getattr(self, 'playback_info', None) or {}).get('item') or {})\n        item.update(getattr(self, 'item', None) or {})\n        if str(item.get('Type') or item.get('type') or '') != 'Episode':\n            return normalized\n        server, token, user = get_emby_auth()\n        server = str(server or '').rstrip('/')\n        item_id = _embyflow_marker_v17_5_3_3_item_id(self)\n        if not (server and token and user and item_id):\n            _eftidb_log('SKIP missing metadata authentication')\n            return normalized\n        headers = {'X-Emby-Token': token, 'X-Emby-Authorization': AUTH_HEADER}\n        def metadata(identifier):\n            response = embyflow_http_get(\n                '%s/Users/%s/Items/%s' % (server, user, identifier),\n                headers=headers, params={'Fields': 'ProviderIds,RunTimeTicks'},\n                timeout=6, verify=True)\n            return response.json() if response.status_code == 200 else {}\n        full = metadata(item_id)\n        if not isinstance(full, dict):\n            return normalized\n        item.update(full)\n        series_id = item.get('SeriesId') or item.get('series_id')\n        season = item.get('ParentIndexNumber')\n        episode = item.get('IndexNumber')\n        duration_ms = int(item.get('RunTimeTicks') or 0) // 10000\n        if not series_id or type(season) is not int or type(episode) is not int:\n            _eftidb_log('SKIP missing series/season/episode')\n            return normalized\n        if season < 0 or episode < 1 or duration_ms <= 0:\n            return normalized\n        series = metadata(series_id)\n        providers = series.get('ProviderIds') or {}\n        tmdb = str(providers.get('Tmdb') or providers.get('TMDb') or '')\n        if not tmdb.isdigit():\n            _eftidb_log('SKIP missing series TMDb ID')\n            return normalized\n        # Fresh request: NEVER reuse server session, headers or auth here.\n        response = requests.get(\n            'https://api.theintrodb.org/v3/media',\n            params={'tmdb_id': tmdb, 'season': season, 'episode': episode,\n                    'duration_ms': duration_ms},\n            headers={'Accept': 'application/json', 'User-Agent': 'EmbyFlowE2-IntroTest/1'},\n            timeout=(4, 6), verify=True, allow_redirects=False)\n        _eftidb_log('LOOKUP tmdb=%s S%s E%s status=%s' %\n                    (tmdb, season, episode, response.status_code))\n        if response.status_code != 200:\n            return normalized\n        data = response.json()\n        if not isinstance(data, dict):\n            return normalized\n        marks = _eftidb_ranges(data, duration_ms)\n        if marks:\n            answer = dict(normalized)\n            answer.update(marks)\n            answer['raw_marker_count'] = len(marks)\n            answer['theintrodb_test'] = True\n            _eftidb_log('FOUND intro=%s-%s credits=%s' %\n                        (marks.get('intro_start', 0), marks.get('intro_end', 0),\n                         marks.get('credits_start', 0)))\n            return answer\n        _eftidb_log('NO_USABLE_MARKERS')\n    except Exception as error:\n        # Log only the class; exception strings can contain private URLs.\n        _eftidb_log('ERROR ' + type(error).__name__)\n    return normalized\n\n\n_EFTIDB_APPLY = _embyflow_marker_v17_5_apply_result\n\ndef _eftidb_apply(self):\n    result = getattr(self, '_embyflow_marker_v17_5_result', None)\n    if (isinstance(result, dict) and result.get('serial') ==\n            getattr(self, '_embyflow_marker_v17_5_serial', -1)):\n        self._eftidb_active = bool(result.get('theintrodb_test'))\n    return _EFTIDB_APPLY(self)\n\n\n_EFTIDB_TICK = _embyflow_marker_v17_5_tick\n\ndef _eftidb_tick(self):\n    if (getattr(self, '_eftidb_active', False)\n            and getattr(self, '_embyflow_marker_v17_5_loaded', False)\n            and not getattr(self, 'closed', False)\n            and not getattr(self, 'paused', False)\n            and not getattr(self, '_embyflow_marker_intro_handled_v17_5', False)):\n        start = int(getattr(self, '_embyflow_marker_intro_start_v17_5', 0) or 0)\n        end = int(getattr(self, '_embyflow_marker_intro_end_v17_5', 0) or 0)\n        position = int(self.current_position_ticks() or 0)\n        if end > start >= 0 and start <= position < end - 50000000:\n            _eftidb_log('AUTO_INTRO position=%s target=%s' % (position, end))\n            _embyflow_marker_v17_5_intro_callback(self, 'skip')\n            return\n    # Existing credits countdown includes cancellation and next-episode handling.\n    return _EFTIDB_TICK(self)\n\n\n_embyflow_marker_v17_5_apply_result = _eftidb_apply\n_embyflow_marker_v17_5_tick = _eftidb_tick\n"

def patch(source):
    if hashlib.sha256(source).hexdigest() != BASE_SHA:
        raise RuntimeError("Andere Pluginversion: Installation sicher abgebrochen.")
    text = source.decode("utf-8")
    begin = text.index("def _embyflow_marker_v17_5_3_3_fetch_worker(")
    end = text.index("# The existing start_fetch routine", begin)
    worker = text[begin:end]
    old = "        result.update(normalized)"
    if worker.count(old) != 1:
        raise RuntimeError("Einbaustelle nicht eindeutig.")
    worker = worker.replace(old, "        normalized = _eftidb_fallback(self, normalized)\n" + old)
    result = text[:begin] + worker + text[end:] + "\n" + LAYER
    ast.parse(result)
    return result.encode("utf-8")

if __name__ == "__main__":
    path = Path(sys.argv[1] if len(sys.argv) > 1 else "/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/plugin.py")
    original = path.read_bytes()
    updated = patch(original)
    if "--check" in sys.argv:
        print("Pruefung bestanden; nichts installiert.")
        sys.exit(0)
    backup = Path(str(path) + ".before_introtest_" + time.strftime("%Y%m%d_%H%M%S"))
    with backup.open("xb") as f:
        f.write(original)
    temporary = Path(str(path) + ".introtest_tmp")
    try:
        temporary.write_bytes(updated)
        os.chmod(str(temporary), path.stat().st_mode & 0o777)
        os.replace(str(temporary), str(path))
    finally:
        if temporary.exists(): temporary.unlink()
    print("INTRO-TEST INSTALLIERT. Sicherung: " + str(backup))
    print("Jetzt GUI ueber das Receiver-Menue neu starten.")
